"""Baseline 5: RT-BarnesHut (Nagarajan et al., SC 2024), branch BarnesHutRT of OWLRayTracing, ~/OWLRayTracing/build/rtbarneshut (built 2026-06-22, PRINT_ARTIFACT true: it prints only preprocessing, RT force time and execution time).
usage: python base_barneshut.py [REPS]   -> notes/base1/barneshut_<ts>.json. Change no code. The program hardcodes CUDA device 1 (gpuDeviceID = 1), so both GPUs are made visible; only ordinal 1 is used."""
import re, sys, base_common as B
REPS = int(sys.argv[1]) if len(sys.argv) > 1 else 5
BIN = B.HOME + '/OWLRayTracing/build/rtbarneshut'; DD = B.HOME + '/thirdparty/base_data'
def parse(t):
    p = {}
    for k, pat in (('preprocessing_s', r'Preprocessing Time: ([0-9.]+)'), ('rt_force_s', r'RT Cores Force Calculations time: ([0-9.]+)'), ('execution_s', r'Execution time: ([0-9.]+)')):
        m = re.search(pat, t); p[k] = float(m.group(1)) if m else None
    return p
doc = B.header('RT-BarnesHut', BIN, [DD + '/bh_g100k.txt', DD + '/bh_g1M.txt'], 'Gaussian disc (x,y sigma 100, z sigma 20, mass uniform 1 to 100, seed 42, generated by model/priorworks/gen_bh_input.py, same recipe as the earlier g100k and g1M files which no longer exist; the 5 header floats are my guess, the program discards them). One force step per run (no steps argument). Preprocessing = tree to DFS + auto ropes + intersection setup; sort and tree build are CPU and are not in the printed preprocessing figure.')
doc['configs'] = []
for name, f in (('g100k', 'bh_g100k.txt'), ('g1M', 'bh_g1M.txt')):
    cmd = [BIN, 'treelogy', DD + '/' + f]; runs = []
    for i in range(REPS):
        x = B.run(cmd, B.HOME + '/OWLRayTracing/build', B.env(cuda_visible='0,1'), 600); x['parsed'] = parse(x['stdout']); runs.append(x)
    doc['configs'].append(dict(name=name, cmd=' '.join(cmd).replace(B.HOME, '~'), runs=runs, summary=B.summarize(runs, ['preprocessing_s', 'rt_force_s', 'execution_s']) | {'wall_s': B.stats([x['wall_s'] for x in runs if x['rc'] == 0])}))
print(B.write('barneshut', doc))
